"""Suíte de regressão do DaisyCare.
Uso:  pip install playwright && playwright install chromium
      python testes/regressao.py app/DaisyCare_App_v40_93_Voz_Natural.html
Sobe um servidor local (para a pasta falas/ funcionar), roda as checagens e imprime OK/FALHA."""
import sys,os,threading,http.server,socketserver,functools
from playwright.sync_api import sync_playwright
html=os.path.abspath(sys.argv[1]);root=os.path.dirname(html);name=os.path.basename(html)
class Q(http.server.SimpleHTTPRequestHandler):
    def log_message(self,*a):pass
srv=socketserver.ThreadingTCPServer(('127.0.0.1',0),functools.partial(Q,directory=root));port=srv.server_address[1]
threading.Thread(target=srv.serve_forever,daemon=True).start()
R=[]
def chk(n,c,extra=''):
    R.append((n,bool(c)));print(('OK     ' if c else 'FALHA  ')+n+(' · '+str(extra) if extra and not c else ''))
def pg2_voz(b,port,name):
    q=b.new_page(viewport={'width':1300,'height':900})
    q.add_init_script("localStorage.setItem('daisycare_prefs_v52','{\"seen\":1}');window.__pl=[];const P=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(){window.__pl.push(this.src||'');return P.apply(this,arguments)}")
    q.goto(f'http://127.0.0.1:{port}/{name}');q.wait_for_timeout(3000);q.evaluate("showPage('appchat')");q.evaluate("window.__DAISY_OFFICIAL_VOICE_4035.active=true")
    # v40.93: a opção 1 virou menu de ação (só texto); a voz é conferida na fila (2) e na agenda (3)
    q.fill('#appInput','2');q.evaluate("sendChat('app')");q.wait_for_timeout(800)
    q.fill('#appInput','menu');q.evaluate("sendChat('app')");q.wait_for_timeout(800)
    q.fill('#appInput','3');q.evaluate("sendChat('app')");q.wait_for_timeout(800)
    t=' '.join(q.evaluate('window.__pl'));q.close()
    return t.count('falas/auto/')>=2

def pg2_nc(b,port,name):
    q=b.new_page(viewport={'width':1300,'height':900})
    q.add_init_script("localStorage.setItem('daisycare_prefs_v52','{\"seen\":1}');window.__pl=[];const P=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(){window.__pl.push(this.src||'');return P.apply(this,arguments)}")
    q.goto(f'http://127.0.0.1:{port}/{name}');q.wait_for_timeout(3000);q.evaluate("showPage('appchat')");q.evaluate("window.__DAISY_OFFICIAL_VOICE_4035.active=true")
    out=[]
    for m in ['nova consulta','ginecologista','2']:
        q.fill('#appInput',m);q.evaluate("sendChat('app')");q.wait_for_timeout(1500)
    txt=q.evaluate("document.querySelector('#appBody').innerText")
    pl=' '.join(q.evaluate('window.__pl'));q.close()
    return ('reservei a opção 2 de ginecologista' in txt.lower(), 'gen_opt.mp3' in pl, 'slot2.mp3' in pl, 'fila digital' not in txt.lower().split('reservei')[-1][:200])
def pg2_mute(b,port,name):
    q=b.new_page(viewport={'width':1300,'height':900})
    q.add_init_script("localStorage.setItem('daisycare_prefs_v52','{\"seen\":1}');window.__pl=[];const P=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(){window.__pl.push((this.src||'').split('/').pop());return P.apply(this,arguments)}")
    q.goto(f'http://127.0.0.1:{port}/{name}');q.wait_for_timeout(3000);q.evaluate("showPage('appchat')")
    tx=lambda:q.evaluate("document.querySelector('#muteBtnApp').textContent")
    n0=q.evaluate("document.querySelectorAll('#appBody .bubble').length")
    q.click('#muteBtnApp');q.wait_for_timeout(4000);a=tx();apres=q.evaluate("document.querySelectorAll('#appBody .bubble').length")>n0
    q.click('#muteBtnApp');q.wait_for_timeout(400);b2=tx()
    q.evaluate("window.__pl=[]");q.fill('#appInput','1');q.evaluate("sendChat('app')");q.wait_for_timeout(2500)
    mudo=q.evaluate("window.__pl")==[]
    q.click('#muteBtnApp');q.wait_for_timeout(400);c=tx()
    body=q.evaluate("document.body.innerText")
    q.close()
    import re
    return (apres and 'ativo' in a,'desligado' in b2,mudo,'ativo' in c,not re.search(r'\bMVP\b',body))
def pg2_prep(b,port,name):
    q=b.new_page(viewport={'width':1300,'height':900})
    q.add_init_script("localStorage.setItem('daisycare_prefs_v52','{\"seen\":1}')")
    q.goto(f'http://127.0.0.1:{port}/{name}');q.wait_for_timeout(3000);q.evaluate("showPage('appchat')")
    r=[]
    for m in ['exames de sangue','exame de urina','procedimentos cirurgicos ou diagnosticos simples']:
        q.fill('#appInput','menu');q.evaluate("sendChat('app')");q.fill('#appInput',m);q.evaluate("sendChat('app')");q.wait_for_timeout(250)
        r.append(any(x in q.evaluate("(()=>{const b=[...document.querySelectorAll('#appBody .bubble')];return b[b.length-1].innerText})()") for x in ('Escolha uma categoria','Digite o número do exame')))
    q.close();return r

